import numpy as np
def build_releases(n_events=6, released=200, survival=0.55, detection=0.9, k=4):
    rows = []
    for a in range(14):
        for j in range(n_events):
            year = 2000 + a + j
            cells = []
            for t in range(k):
                q = survival ** (t + 1) * detection * (1 - detection) ** t
                cells.append(int(round(released * q)))
            never = released - sum(cells)
            rows.append([year, year - a - 1, released, int(round(never * 0.2))] + cells)
    return np.array(rows, dtype=int)
def build_reproduction():
    return np.array([[2000 + age, 2000, 50, 35, 60] for age in range(2, 14)], dtype=int)
REL = build_releases()
REC = build_reproduction()
assert np.allclose(relative_reproductive_value(REL, REC), target)

